class Solution {
public:
    vector<string> binaryTreePaths(TreeNode* root) {
        if (!root) return {};
        vector<string> res;
        dfs(root, to_string(root->val), res);
        return res;
    }
private:
    void dfs(TreeNode* node, string path, vector<string>& res) {
        if (!node->left && !node->right) {
            res.push_back(path);
            return;
        }
        if (node->left) dfs(node->left, path + "->" + to_string(node->left->val), res);
        if (node->right) dfs(node->right, path + "->" + to_string(node->right->val), res);
    }
};

class Solution {
    public List<String> binaryTreePaths(TreeNode root) {
        List<String> res = new ArrayList<>();
        if (root == null) return res;
        dfs(root, String.valueOf(root.val), res);
        return res;
    }
    private void dfs(TreeNode node, String path, List<String> res) {
        if (node.left == null && node.right == null) {
            res.add(path);
            return;
        }
        if (node.left != null) dfs(node.left, path + "->" + node.left.val, res);
        if (node.right != null) dfs(node.right, path + "->" + node.right.val, res);
    }
}

